export function toCamelCase(str) {if (!str || typeof str !== 'string') return '';return str.replace(/-([a-z0-9])/gi, (_, char) => char.toUpperCase());}export class BlewApiRouter {constructor(routes) {this.routes = Array.isArray(routes) ? routes : [];this._compiledRoutes = [];this._compileRoutes();}_compileRoutes() {if (typeof URLPattern === 'undefined') return;this._compiledRoutes = this.routes.map((route) => {const pattern = new URLPattern({ pathname: route.pattern });return { pattern, route };});}async handle(request) {if (!request || !(request instanceof Request)) {return new Response(JSON.stringify({ error: 'Bad Request: Invalid Request object' }), {status: 400,headers: { 'Content-Type': 'application/json' }});}const url = new URL(request.url);const apiIdx = url.pathname.indexOf('/api/');const pathname = apiIdx > 0 ? url.pathname.slice(apiIdx) : url.pathname;for (const { pattern, route } of this._compiledRoutes) {const result = pattern.exec({ pathname });if (!result) continue;const params = {};const groups = result.pathname?.groups || {};for (const [key, value] of Object.entries(groups)) {if (value !== undefined) {params[key] = value;}}const context = {params,url};let endpointModule;try {endpointModule = typeof route.load === 'function' ? await route.load() : route.load;} catch (err) {console.error(`Failed to load endpoint for ${route.pattern}:`, err);return new Response(JSON.stringify({ error: 'Internal Server Error' }), {status: 500,headers: { 'Content-Type': 'application/json' }});}if (!endpointModule || typeof endpointModule !== 'object') {return new Response(JSON.stringify({ error: 'Endpoint Module Not Found' }), {status: 500,headers: { 'Content-Type': 'application/json' }});}const rawAction = params.action ? params.action.split('/')[0] : '';if (rawAction) {const camelAction = toCamelCase(rawAction);if (typeof endpointModule[camelAction] === 'function') {try {return await endpointModule[camelAction](request, context);} catch (err) {console.error(`Error in named action '${camelAction}':`, err);return new Response(JSON.stringify({ error: 'Internal Action Error' }), {status: 500,headers: { 'Content-Type': 'application/json' }});}}}const method = request.method ? request.method.toUpperCase() : 'GET';if (typeof endpointModule[method] === 'function') {try {return await endpointModule[method](request, context);} catch (err) {console.error(`Error in HTTP verb '${method}':`, err);return new Response(JSON.stringify({ error: 'Internal Handler Error' }), {status: 500,headers: { 'Content-Type': 'application/json' }});}}return new Response(JSON.stringify({ error: `Method Not Allowed: ${method}` }),{status: 405,headers: { 'Content-Type': 'application/json' }});}return new Response(JSON.stringify({ error: 'Not Found or Disabled' }),{status: 404,headers: { 'Content-Type': 'application/json' }});}}